package cn.mop.api;
import cn.mop.adapters.monitoring.ZabbixNumericHistoryProtocol;
import cn.mop.adapters.monitoring.ZabbixNumericHistoryProtocol.*;
import cn.mop.domain.monitoring.MetricSeriesProjection.Scope;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.Test;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
/** Synthetic protocol messages only; no transport, credentials, actual Zabbix or monitoring verification. */
class ZabbixNumericHistoryProtocolTest {
    final ObjectMapper json=new ObjectMapper();
    final Scope scope=new Scope(UUID.fromString("88000000-0000-4000-8000-000000000001"),UUID.fromString("88000000-0000-4000-8000-000000000002"),"interface.traffic.in");
    final ExplicitBinding binding=new ExplicitBinding(scope,UUID.fromString("88000000-0000-4000-8000-000000000003"),"23296","explicit-mapping-v1");
    Query query(ValueType type){return new Query(binding,type,1_700_000_000,1_700_000_060,7);}
    ObjectNode point(String clock,String ns,String value){return json.createObjectNode().put("itemid","23296").put("clock",clock).put("ns",ns).put("value",value);}
    ObjectNode point(String ns){return point("1700000000",ns,"0.085");}
    ObjectNode response(JsonNode...rows){var root=json.createObjectNode().put("jsonrpc","2.0").put("id",7);var array=root.putArray("result");for(var row:rows)array.add(row);return root;}
    byte[] bytes(JsonNode value){try{return json.writeValueAsBytes(value);}catch(Exception e){throw new AssertionError(e);}}
    Result decode(ObjectNode value){return ZabbixNumericHistoryProtocol.decode(query(ValueType.NUMERIC_FLOAT),200,"application/json",bytes(value));}
    @Test void requestIsSingleItemExplicitTypeAndBoundedInclusiveHistoryOnly()throws Exception{
        var root=json.readTree(ZabbixNumericHistoryProtocol.request(query(ValueType.NUMERIC_FLOAT)));assertEquals("history.get",root.get("method").textValue());assertEquals(7,root.get("id").intValue());assertEquals(4,root.size());assertFalse(root.has("auth"));var p=root.get("params");assertEquals(0,p.get("history").intValue());assertEquals(List.of("23296"),json.convertValue(p.get("itemids"),List.class));assertEquals(List.of("itemid","clock","ns","value"),json.convertValue(p.get("output"),List.class));assertEquals(List.of("clock","ns"),json.convertValue(p.get("sortfield"),List.class));assertEquals("ASC",p.get("sortorder").textValue());assertEquals(10001,p.get("limit").intValue());assertEquals(1700000000,p.get("time_from").longValue());assertEquals(1700000060,p.get("time_till").longValue());assertFalse(p.has("hostids"));assertFalse(p.has("search"));
    }
    @Test void unsignedTypeIsAlwaysExplicitInsteadOfProviderDefault()throws Exception{assertEquals(3,json.readTree(ZabbixNumericHistoryProtocol.request(query(ValueType.NUMERIC_UNSIGNED))).path("params").path("history").intValue());}
    @Test void decodeRetainsExactDecimalAndSourceReceivedNanoseconds(){var result=decode(response(point("563157632")));assertEquals(Outcome.POINTS_DECODED,result.outcome());var sample=result.samples().get(0);assertEquals("0.085",sample.originalValue());assertEquals(Instant.ofEpochSecond(1700000000,563157632),sample.receivedAt());assertEquals("23296:1700000000:563157632",sample.sourceRecordKey());}
    @Test void twoNanosecondPointsWithinSameMillisecondRemainSeparate(){var r=decode(response(point("1"),point("2")));assertEquals(2,r.samples().size());assertNotEquals(r.samples().get(0).receivedAt(),r.samples().get(1).receivedAt());}
    @Test void unsigned64MaximumAndUnsafeJavascriptIntegersRemainStrings(){for(String value:List.of("0","9007199254740993","18446744073709551615")){var r=ZabbixNumericHistoryProtocol.decode(query(ValueType.NUMERIC_UNSIGNED),200,"application/json",bytes(response(point("1700000000","0",value))));assertEquals(Outcome.POINTS_DECODED,r.outcome());assertEquals(value,r.samples().get(0).originalValue());}}
    @Test void unsignedOutOfRangeNegativeFractionAndLeadingZeroAreUnsupported(){for(String value:List.of("18446744073709551616","-1","1.5","01")){var r=ZabbixNumericHistoryProtocol.decode(query(ValueType.NUMERIC_UNSIGNED),200,"application/json",bytes(response(point("1700000000","0",value))));assertEquals(Outcome.UNSUPPORTED_NUMERIC_ENCODING,r.outcome());assertNull(r.samples());}}
    @Test void floatPlainEncodingPreservesNegativeAndDecimalTrailingZeros(){for(String v:List.of("-12.500","0","0.000","9007199254740993.125")){var r=decode(response(point("1700000000","0",v)));assertEquals(Outcome.POINTS_DECODED,r.outcome());assertEquals(v,r.samples().get(0).originalValue());}}
    @Test void unsupportedNumericEncodingIsExplicitNotRoundedOrConvertedToUnknownSuccess(){for(String v:List.of("1e3","NaN","Infinity","-0","-0.000"," 1","01","1.","0."+"1".repeat(41))){var r=decode(response(point("1700000000","0",v)));assertEquals(Outcome.UNSUPPORTED_NUMERIC_ENCODING,r.outcome(),v);assertNull(r.samples());}}
    @Test void numericJsonInsteadOfDocumentedStringIsNotCoercedThroughDouble(){var r=point("0");r.put("value",0.1);assertEquals(Outcome.UNSUPPORTED_NUMERIC_ENCODING,decode(response(r)).outcome());r=point("0");r.put("clock",1700000000);assertEquals(Outcome.PROTOCOL_ERROR,decode(response(r)).outcome());}
    @Test void anotherItemOrUnrequestedFieldsInvalidateWholeResult(){var other=point("2").put("itemid","23297");assertEquals(Outcome.PROTOCOL_ERROR,decode(response(point("1"),other)).outcome());assertNull(decode(response(point("1"),other)).samples());assertEquals(Outcome.PROTOCOL_ERROR,decode(response(point("1").put("secret","SYNTHETIC"))).outcome());}
    @Test void mismatchedMissingAndFloatingRequestIdsNeverMatch(){for(JsonNode id:List.of(json.getNodeFactory().numberNode(8),json.getNodeFactory().textNode("7"),json.getNodeFactory().numberNode(7.0),json.nullNode())){var root=response(point("0"));root.set("id",id);assertEquals(Outcome.PROTOCOL_ERROR,decode(root).outcome());}var r=response();r.remove("id");assertEquals(Outcome.PROTOCOL_ERROR,decode(r).outcome());}
    @Test void duplicateKeysTrailingJsonAndMalformedUtf8AreRejected(){for(String value:List.of("{\"jsonrpc\":\"2.0\",\"id\":7,\"id\":7,\"result\":[]}",response().toString()+" {}")){assertEquals(Outcome.PROTOCOL_ERROR,ZabbixNumericHistoryProtocol.decode(query(ValueType.NUMERIC_FLOAT),200,"application/json",value.getBytes(StandardCharsets.UTF_8)).outcome());}assertEquals(Outcome.PROTOCOL_ERROR,ZabbixNumericHistoryProtocol.decode(query(ValueType.NUMERIC_FLOAT),200,"application/json",new byte[]{(byte)0xc3,0x28}).outcome());}
    @Test void responseStatusAndMediaTypeDoNotMasqueradeAsEmptySuccess(){for(int status:new int[]{201,204,302,401,403,500})assertEquals(Outcome.HTTP_ERROR,ZabbixNumericHistoryProtocol.decode(query(ValueType.NUMERIC_FLOAT),status,"application/json",bytes(response())).outcome());for(String type:Arrays.asList(null,"text/html","application/json; charset=latin1","application/json,application/json","application/json; charset=utf-8;other=1"))assertEquals(Outcome.PROTOCOL_ERROR,ZabbixNumericHistoryProtocol.decode(query(ValueType.NUMERIC_FLOAT),200,type,bytes(response())).outcome());}
    @Test void jsonRpcMediaTypeAndUtf8ParameterAreAccepted(){for(String type:List.of("application/json","application/json-rpc","application/json; charset=\"UTF-8\""))assertEquals(Outcome.POINTS_DECODED,ZabbixNumericHistoryProtocol.decode(query(ValueType.NUMERIC_FLOAT),200,type,bytes(response())).outcome());}
    @Test void apiErrorIsSanitizedAndCannotHaveCompetingResult(){var root=json.createObjectNode().put("jsonrpc","2.0").put("id",7);root.putObject("error").put("code",-32602).put("message","SYNTHETIC_NOT_SECRET").put("data","SYNTHETIC_DATA");var result=decode(root);assertEquals(Outcome.API_ERROR,result.outcome());assertNull(result.samples());assertNull(result.decodedCount());root.putArray("result");assertEquals(Outcome.PROTOCOL_ERROR,decode(root).outcome());}
    @Test void duplicateAndDescendingClockNanosecondTuplesAreNotDeduplicated(){for(ObjectNode root:List.of(response(point("1"),point("1")),response(point("2"),point("1")),response(point("1700000001","0","1"),point("1700000000","999999999","1")))){assertEquals(Outcome.PROTOCOL_ERROR,decode(root).outcome());assertNull(decode(root).samples());}}
    @Test void wholeSecondBoundsAreInclusiveEvenAtLastNanosecond(){assertEquals(Outcome.POINTS_DECODED,decode(response(point("1700000000","0","1"),point("1700000060","999999999","1"))).outcome());for(String clock:List.of("1699999999","1700000061"))assertEquals(Outcome.PROTOCOL_ERROR,decode(response(point(clock,"0","1"))).outcome());}
    @Test void invalidClockAndNanosecondRepresentationsFailClosed(){for(String ns:List.of("-1","1000000000","00","0.1","1e2",""))assertEquals(Outcome.PROTOCOL_ERROR,decode(response(point(ns))).outcome());for(String c:List.of("-1","1700000000.0","01700000000","999999999999"))assertEquals(Outcome.PROTOCOL_ERROR,decode(response(point(c,"0","1"))).outcome());}
    @Test void maximumPointsAcceptedButSentinelRowMakesLimitFailureWithNoPartialList(){var root=response();var list=(ArrayNode)root.get("result");for(int i=0;i<10000;i++)list.add(point(Integer.toString(i)));assertEquals(10000,decode(root).samples().size());list.add(point("10000"));var result=decode(root);assertEquals(Outcome.POINT_LIMIT_EXCEEDED,result.outcome());assertNull(result.samples());assertNull(result.decodedCount());}
    @Test void oversizeAndNullBodiesAreNotParsed(){assertEquals(Outcome.RESPONSE_TOO_LARGE,ZabbixNumericHistoryProtocol.decode(query(ValueType.NUMERIC_FLOAT),200,"application/json",new byte[ZabbixNumericHistoryProtocol.MAX_RESPONSE_BYTES+1]).outcome());for(byte[] body:Arrays.asList(null,new byte[0]))assertEquals(Outcome.PROTOCOL_ERROR,ZabbixNumericHistoryProtocol.decode(query(ValueType.NUMERIC_FLOAT),200,"application/json",body).outcome());}
    @Test void absentFieldsWrongRootAndNullRowsAreProtocolErrors(){for(ObjectNode root:List.of(response(json.nullNode()),response(point("0")).put("jsonrpc","1.0"),response().put("extra",true))){assertEquals(Outcome.PROTOCOL_ERROR,decode(root).outcome());}for(String field:List.of("itemid","clock","ns","value")){var p=point("0");p.remove(field);assertEquals(Outcome.PROTOCOL_ERROR,decode(response(p)).outcome());}}
    @Test void queryRequiresExplicitPoolItemScopeVersionAndBounds(){for(String item:List.of("0","01","18446744073709551616","1/2","1\n"))assertThrows(IllegalArgumentException.class,()->new ExplicitBinding(scope,binding.resourcePoolId(),item,"v1"));assertThrows(IllegalArgumentException.class,()->new ExplicitBinding(scope,null,"1","v1"));assertThrows(IllegalArgumentException.class,()->new Query(binding,null,0,1,1));assertThrows(IllegalArgumentException.class,()->new Query(binding,ValueType.NUMERIC_FLOAT,2,1,1));assertThrows(IllegalArgumentException.class,()->new Query(binding,ValueType.NUMERIC_FLOAT,-1,1,1));assertThrows(IllegalArgumentException.class,()->new Query(binding,ValueType.NUMERIC_FLOAT,0,1,0));assertThrows(IllegalArgumentException.class,()->new Query(binding,ValueType.NUMERIC_FLOAT,0,1,9007199254740992L));}
    @Test void samplesAndBindingAreImmutableAndDoNotEstablishMonitoringAuthority(){var r=decode(response(point("0")));assertThrows(UnsupportedOperationException.class,()->r.samples().clear());assertEquals(scope,r.query().binding().scope());assertFalse(r.sourceVerified());assertFalse(r.mappingVerified());assertFalse(r.authorizationVerified());assertFalse(r.credentialsUsed());assertFalse(r.transportPerformed());assertFalse(r.completeWindowClaimed());assertNull(r.monitoringReady());assertEquals("SOURCE_RECEIVED_TIME_NOT_VERIFIED_PROBE_TIME",r.timestampMeaning());}
    @Test void emptyProviderResultIsDistinctButNotProofOfCompleteRetentionOrHealthyDevice(){var r=decode(response());assertEquals(List.of(),r.samples());assertEquals(0,r.decodedCount());assertFalse(r.completeWindowClaimed());assertNull(r.monitoringReady());}
    @Test void malformedApiErrorsAreProtocolErrorsInsteadOfParsedProviderDecisions(){
        for(ObjectNode error:List.of(json.createObjectNode(),json.createObjectNode().put("code",-32602).put("message",false),json.createObjectNode().put("code","-32602").put("message","synthetic"),json.createObjectNode().put("code",-32602).put("message","synthetic").put("extra",true))){
            var root=json.createObjectNode().put("jsonrpc","2.0").put("id",7);root.set("error",error);assertEquals(Outcome.PROTOCOL_ERROR,decode(root).outcome());
        }
    }
    @Test void sampleConstructorCannotManufactureInvalidClockNanosecondsOrNumericValues(){
        assertThrows(IllegalArgumentException.class,()->new Sample("23296",ValueType.NUMERIC_FLOAT,0,1000000000,"1"));
        assertThrows(IllegalArgumentException.class,()->new Sample("23296",ValueType.NUMERIC_FLOAT,-1,0,"1"));
        assertThrows(IllegalArgumentException.class,()->new Sample("23296",ValueType.NUMERIC_UNSIGNED,0,0,"-1"));
        assertThrows(IllegalArgumentException.class,()->new Sample("0",ValueType.NUMERIC_FLOAT,0,0,"1"));
    }

}
